const input = $input.first().json;
const body = input.body && typeof input.body === "object" && !Array.isArray(input.body) ? input.body : {};
const get = (a,b) => Object.prototype.hasOwnProperty.call(body,a) ? body[a] : body[b];
const id = typeof get("event_id","eventId") === "string" ? get("event_id","eventId").trim() : "";
const rawSource = get("source","origin");
const source = typeof rawSource === "string" ? rawSource.trim().toLowerCase() : "";
const errors = [];
if (!/^[A-Za-z0-9][A-Za-z0-9._:-]{5,127}$/.test(id)) errors.push("event_id must be a stable string of 6-128 letters, numbers, dots, underscores, colons or hyphens");
if (!/^[a-z][a-z0-9._-]{1,39}$/.test(source)) errors.push("source must be a stable system name of 2-40 lowercase letters, numbers, dots, underscores or hyphens");
if (Object.keys(body).length > 30) errors.push("too many top-level fields");
const valid = errors.length === 0;
return [{json:{
  valid,
  eventId: valid ? id : null,
  source: valid ? source : null,
  eventKey: valid ? source + ":" + id : null,
  error: valid ? null : {code:"invalid_event_envelope",details:errors}
}}];
